-- 业务类型映射
delete from BUSI_TYPE_MAPPING where SEQNO in ('8','9');

--初始化from表单
--质押式回购首期-指令上不指定质押券模式
delete from CFG_READONLY_FORM_SHOW where PAGECODE='CfetsEtrDispatcher' and DTCODE='CfetsEtrDispatcherInfo' and SPCDCODE='05,01';

--质押式回购首期-指令上指定质押券库模式
delete from CFG_READONLY_FORM_SHOW where PAGECODE='CfetsEtrDispatcher' and DTCODE='CfetsEtrDispatcherInfo' and SPCDCODE in ('05,03','05,03,03');

--质押式回购首期-指令上指定质押券模式
delete from CFG_READONLY_FORM_SHOW where PAGECODE='CfetsEtrDispatcher' and DTCODE='CfetsEtrDispatcherInfo' and SPCDCODE in ('05,02','05,02,03');
--正回购显示
delete from CFG_DATATABLE_SHOW where PAGECODE='CfetsEtrDispatcher' and DTCODE='CfetsEtrDispatcherInfo' and SPCDCODE ='05,02,03';


--指令执行
delete from CFG_DATATABLE_SHOW where PAGECODE='CfetsEtrDispatcher' and DTCODE='CfetsEtrDispatcherExeInfo' and SPCDCODE ='05';

--指令成交
delete from CFG_DATATABLE_SHOW where PAGECODE='CfetsEtrDispatcher' and DTCODE='CfetsEtrDispatcherDealInfo' and SPCDCODE ='05';
